    "Aceitar mensagens de grupos, canais e comunidades — desligue para receber só a conversa direta com o número da live": "グループ・チャンネル・コミュニティからのメッセージを受け取る — オフにすると、配信用の番号との個別のやり取りだけが届きます",
    "Só a conversa direta está entrando — ligue os grupos acima para usar este campo.": "個別のやり取りだけが入っています。この欄を使うには上のグループをオンにしてください。",
