    "✍️ Transcrição": "✍️ 文字起こし",
    // 📱 v0.139: a personalização do QR
    "📱 O código em si": "📱 コードそのもの",
    "As cores acima são do cartão que segura o QR; estas aqui são do código em si. Nada disto muda o que o QR carrega — só o desenho.": "上の色はQRを載せているカードのもの、ここの色はコードそのもののです。どれもQRの中身は変えません —— 見た目だけです。",
    "Clássico": "クラシック",
    "Suave": "やわらか",
