    "⬇️ Salvar meu tema num arquivo": "⬇️ テーマをファイルに保存",
    "⬆️ Carregar tema de um arquivo": "⬆️ ファイルからテーマを読み込む",
    "Dá para guardar o seu tema e usar em outro computador — ou compartilhar com outros streamers.": "テーマを保存して別のパソコンで使ったり、ほかの配信者と共有したりできます。",
    "Voltar ao padrão": "既定に戻す",
