    "🔥 Brasa": "🔥 エンバー",
    "🌸 Rosa neon": "🌸 ネオンピンク",
    "☀️ Claro suave": "☀️ やわらかライト",
    "📜 Papel": "📜 ペーパー",
    "⚡ Alto contraste": "⚡ ハイコントラスト",
    "👾 Retrô": "👾 レトロ",
    "Carregar tema": "テーマを読み込む",
    "Voltar ao tema padrão do OBS Social? As cores e ajustes que você mudou aqui serão descartados.": "OBS Social の標準テーマに戻しますか？ ここで変更した色や設定は破棄されます。",
    "Não consegui ler esse arquivo de tema. Ele precisa ser um tema salvo pelo OBS Social.": "このテーマファイルを読み込めませんでした。OBS Social で保存したテーマが必要です。",
    "Carregar este tema? Ele substitui as cores e os ajustes de aparência que estão valendo agora.": "このテーマを読み込みますか？ 現在の色と外観の設定を置き換えます。",
    '🗄️ Logs e dados': "🗄️ ログとデータ",
    "🧹 Limpeza de dados": "🧹 データの削除",
    'A live parece estar offline (o chat continua conectado)': "配信はオフラインのようです（チャットは接続されたままです）",
    // ---------- idioma ----------
    'Idioma do sistema': 'システムの言語',
    '🌐 Idioma': '🌐 言語',
    'Idioma da interface': 'インターフェースの言語',
    'Escolha o idioma do OBS Social. "Idioma do sistema" segue o idioma do navegador/computador de quem abre cada página. A mudança vale para o painel, as configurações e os overlays — na hora, sem reiniciar.':
      'OBS Socialの言語を選択します。「システムの言語」は、各ページを開く人のブラウザ／パソコンの言語に従います。変更はパネル、設定、オーバーレイに即時反映され、再起動は不要です。',
    'O que não tiver tradução aparece em português. Textos escritos por você ou pelos espectadores (nomes, mensagens do chat, títulos dos widgets) nunca são traduzidos.':
      '翻訳がないものはポルトガル語で表示されます。あなたや視聴者が書いたテキスト（名前、チャットメッセージ、ウィジェットのタイトル）は翻訳されません。',

