    '🧰 Ferramentas (QR, sorteio, likômetro, winstreak, audiência, doações)': '🧰 ツール（QR・抽選・いいねメーター・Winstreak・視聴者数・投げ銭）',
    '⚙️ Mudar configurações e organizar a tela': '⚙️ 設定変更と画面の配置',
