    'A Bilibili é experimental — ative em Configurações → 🧪 Labs para usar.': 'Bilibiliは実験的機能です — 設定 → 🧪 Labs でオンにしてください。',
    'O OBS Social só aceita conexões da rede local.': 'OBS Socialはローカルネットワークからの接続のみ受け付けます。',
