    'Falha ao gravar o arquivo.': 'ファイルの保存に失敗しました。',
    'Não encontrado': '見つかりません',
    'Conecte o YouTube primeiro (na engrenagem).': '先にYouTubeを接続してください（歯車アイコンから）。',
    'Não consegui ler os números (a live está no ar?)': '数値を読み取れませんでした（配信は放送中ですか？）',
    'YouTube não devolveu os números': 'YouTubeから数値が返ってきませんでした',
    'não consegui ler o número de espectadores (formato mudou?)': '視聴者数を読み取れませんでした（形式が変わった？）',
    'consulta recusada': 'クエリが拒否されました',
    'erro desconhecido': '不明なエラー',
    'tempo esgotado (60s)': 'タイムアウト（60秒）',
    'o GitHub respondeu': 'GitHubの応答:',
    'arquivo baixado não é um ZIP válido': 'ダウンロードしたファイルが有効なZIPではありません',
    'não achei o package.json na atualização': 'アップデート内にpackage.jsonが見つかりませんでした',
    '— o pacote de atualização não está acessível agora. Tente de novo mais tarde.': '— アップデートパッケージに今アクセスできません。後でもう一度お試しください。',
    '— parece um antivírus/firewall com "inspeção HTTPS" interceptando a conexão. Atualize o Node.js para a versão LTS mais nova em nodejs.org (aí o programa passa a confiar nos certificados do Windows) ou desative a inspeção HTTPS do antivírus para o Node.':
      '— アンチウイルス／ファイアウォールの「HTTPS検査」が接続を傍受しているようです。nodejs.org から最新LTSのNode.jsに更新するか（そうするとプログラムがWindowsの証明書を信頼するようになります）、アンチウイルスのHTTPS検査からNodeを除外してください。',

