    "só aqui no editor": "このエディター内でのみ非表示にします",
    ", para trabalhar com calma; o 🔒 trava a camada para você não esbarrar nela sem querer.": "。落ち着いて作業できます。🔒 はレイヤーをロックして、うっかり触らないようにします。",
