    "Deixe o OBS Social com a sua cara: cores, imagem de fundo, tamanhos de texto e de ícones, cantos e espaçamento. Isto muda o": "OBS Social をあなた色に: 色・背景画像・文字とアイコンのサイズ・角・余白。変わるのは",
