    "— ao carregar um tema, o cartão do destaque, o chat fixo e os widgets ganham as cores, os cantos e a fonte dele (o QR mantém o fundo branco, para continuar escaneável)": "— テーマを読み込むと、注目カード・固定チャット・ウィジェットがその色・角・フォントを受け取ります（QR はスキャンできるよう白背景のまま）",
