    "Recursos para o OBS Social funcionar bem para todo mundo. Cada um tem o seu liga/desliga e vale no": "OBS Social をすべての人に使いやすくする機能。それぞれにスイッチがあり、適用先は",
    "painel e nas configurações": "パネルと設定",
