    "Para baixa visão. Combina com o tema ⚡ Alto contraste da aba 🎨 Temas (preto + amarelo), que muda as cores da interface inteira.": "ロービジョン向け。🎨 テーマタブの ⚡ ハイコントラストテーマ（黒＋黄）と組み合わせると、インターフェース全体の色が変わります。",
