    "— corta as animações e transições da interface": "— インターフェースのアニメーションとトランジションを止めます",
    "Para quem tem sensibilidade a movimento (enjoo, epilepsia fotossensível, TDAH). As animações do overlay na live não mudam — elas são parte do seu show.": "動きに敏感な方へ（乗り物酔い・光感受性てんかん・ADHD）。配信中のオーバーレイのアニメは変わりません — あなたのショーの一部です。",
