    "Para quem usa o teclado em vez do mouse (mobilidade reduzida, leitores de tela).": "マウスの代わりにキーボードを使う方へ（運動機能の制約・スクリーンリーダー）。",
    "Formas além de cor no status": "状態に色以外の形も",
    "— a bolinha das conexões ganha ✓ (live no ar), ! (sem live) e ✕ (falhou)": "— 接続の丸印に ✓（配信中）、!（配信なし）、✕（失敗）が付きます",
    "Para daltonismo: verde, amarelo e vermelho deixam de ser a única pista.": "色覚多様性向け: 緑・黄・赤だけが手がかりではなくなります。",
    "💡 Também ajudam (já existem em outras abas)": "💡 これらも役立ちます（他のタブに既にあります）",
    "(no painel) amplia tudo de uma vez; o": "（パネルの）は全体を一度に拡大;",
    "Tamanho dos textos": "文字サイズ",
    "e a": "と",
    "fonte": "フォント",
    "ficam na aba 🎨 Temas; os avisos importantes aparecem como texto (nunca só como som); e as dicas dos botões são lidas por leitores de tela. Falta algo para você? Conte na aba 📣 Feedback — acessibilidade é prioridade.": "は 🎨 テーマタブに。重要な警告は必ずテキストで表示（音だけには頼りません）。ボタンのヒントはスクリーンリーダーが読み上げます。足りないものがあれば 📣 フィードバックタブへ — アクセシビリティは優先事項です。",
