    // ---------- v0.45.0: animação dos comentários, sorteio espelhado e pendências do relógio ----------
    "🫧 Chegada dos comentários no painel": "🫧 パネルへのコメント登場",
    "Deslizar de baixo (padrão)": "下からスライド（既定）",
