    "Zoom (vir de perto)": "ズーム（近づく）",
    "Quicar": "バウンド",
    "Duração:": "長さ:",
    "Vale para a aba Ao vivo e para as colunas do painel: só o comentário": "ライブタブとパネルの列に適用：アニメーションするのは",
    "que chega": "届いたコメントだけ",
    "anima — os que já estavam na tela ficam parados. Com ♿ Acessibilidade → Sem animações ligado, nada anima.": "——すでに画面にあるものは動きません。♿アクセシビリティ→アニメーションなしがオンなら何も動きません。",
    "Tudo apagado: o OBS Social voltou ao padrão de fábrica e vai REINICIAR sozinho em instantes (pelo mesmo caminho da atualização). Esta página recarrega quando ele voltar.": "すべて削除：OBS Socialは工場出荷時に戻り、まもなく自動で再起動します（更新と同じ経路で）。戻ったらこのページは再読み込みされます。",
    "Ao terminar, o programa REINICIA sozinho (como na atualização)": "完了すると、プログラムは自動で再起動します（更新時と同じ）",
    "Este é o MESMO pódio da tela do OBS (widget 🎁), com o mesmo dado 🎲 e as mesmas configurações — o suspense aqui é o do seu público. Fechar no ✖ acima não tira da tela.": "これはOBS画面と同じ表彰台です（🎁ウィジェット）。同じサイコロ🎲、同じ設定——ここのドキドキは視聴者と同じもの。上の✖はここだけを閉じ、画面からは消しません。",
    "✖ Tirar o pódio da tela": "✖ 表彰台を画面から下げる",
    "Tirar o pódio da tela do OBS (o mesmo botão da ferramenta 🎁)": "表彰台をOBS画面から下げる（🎁ツールと同じボタン）",
