    "🖼️ Imagens e vídeos enviados": "🖼️ アップロードした画像と動画",
    // ---------- v0.52.1: avulsa vs. assinatura ----------
    "💸 Doação avulsa": "💸 一回きりの寄付",
    "uma vez só, o valor que você quiser": "一度だけ、好きな金額で",
    "🔁 Apoio mensal": "🔁 毎月の応援",
    "renova todo mês, dá para cancelar quando quiser": "毎月更新、いつでも解約できます",
    "⚡ Amigos do OBS Social": "⚡ OBS Social の仲間",
    "no LivePix · Pix ou cartão": "LivePix で · Pix またはカード",
    "💜 assinar": "💜 登録する",
    "Isto é uma assinatura, diferente das doações de cima: ela se repete todo mês até você cancelar (o cancelamento é na sua conta do LivePix, sem falar com ninguém). Nenhum recurso do programa depende disso — tudo continua grátis para todo mundo, sempre.": "これは上の寄付とは違い、サブスクです。解約するまで毎月くり返されます（解約はご自身の LivePix アカウントで、誰かに連絡する必要はありません）。プログラムのどの機能もこれに依存しません — すべて、いつでも、誰にでも無料のままです。",
    "Aqui fica o ⬅ de voltar quando a pasta está aberta": "フォルダーを開いているとき、ここに ⬅ 戻るが入ります",
    "Aqui fica o ⬅ de voltar quando a pasta está aberta — solte uma tecla aqui para tirá-la desta pasta": "フォルダーを開いているとき、ここに ⬅ 戻るが入ります — キーをここに落とすとこのフォルダーから出ます",
