    "A escala do OBS vai de -100 dB (mudo) a +26 dB. 0 dB é o volume cheio da fonte.": "OBS の目盛りは -100 dB（無音）から +26 dB まで。0 dB がソースの最大音量です。",
    "Em milissegundos (1000 = 1 segundo). 0 = não mexe na duração que já está no OBS.": "ミリ秒（1000 = 1 秒）。0 = OBS に設定済みの長さをそのままにします。",
    "Escolha o que esta tecla faz no OBS. As listas de cenas, fontes e filtros vêm do OBS conectado — sem conexão, dá para digitar o nome na mão.": "このキーが OBS で何をするか選びます。シーン・ソース・フィルタの一覧は接続中の OBS から来ます — 未接続でも名前を手で入力できます。",
    "🎵 toca um som · 🎬 Ação do OBS: comanda o OBS Studio (gravar, trocar de cena, mudo...) · 🎛️ Botão de multi ação: guarda teclas e o clique toca tudo em fila (segurar abre) · 📁 Pasta simples: só guarda teclas — o clique abre, nada toca": "🎵 音を鳴らす · 🎬 OBS の操作：OBS Studio を操作（録画、シーン切り替え、ミュートなど） · 🎛️ マルチアクションボタン：キーをまとめ、クリックで順番に全部再生（長押しで開く） · 📁 シンプルフォルダ：キーを入れるだけ — クリックで開き、何も鳴りません",
