    "Tocar / pausar": "再生 / 一時停止",
    "Pausar/continuar a gravação": "録画を一時停止/再開",
    "Marcador de capítulo na gravação (OBS 30.2+, gravação Hybrid MP4)": "録画にチャプターマーカー（OBS 30.2 以降、Hybrid MP4 録画）",
