    "Print da cena no ar — cai direto nas mídias do programa": "本番中のシーンのキャプチャ — そのままプログラムのメディアに入ります",
    "⏺ gravação PAUSADA": "⏺ 録画 一時停止中",
    "📷 câmera virtual ligada": "📷 仮想カメラ オン",
    "⏪ replay buffer ligado": "⏪ リプレイバッファ オン",
    "Desligar a câmera virtual do OBS?": "OBS の仮想カメラをオフにしますか？",
    "Ligar a câmera virtual do OBS?": "OBS の仮想カメラをオンにしますか？",
    "não sei o que capturar: o OBS não tem cena no ar": "何をキャプチャすればよいか分かりません：OBS に本番中のシーンがありません",
    "print vazio ou grande demais": "キャプチャが空、または大きすぎます",
    "replay salvo pelo OBS": "OBS がリプレイを保存しました",
    "o replay buffer está desligado — ligue antes de salvar": "リプレイバッファがオフです — 保存する前にオンにしてください",
    "marcador de capítulo pede OBS 30.2 ou mais novo": "チャプターマーカーには OBS 30.2 以降が必要です",
    "o preview só existe com o modo estúdio ligado": "プレビューはスタジオモードがオンのときだけあります",
    "a transição de estúdio pede o modo estúdio ligado": "スタジオトランジションにはスタジオモードのオンが必要です",
    "🎛️ O que aparece no controle do OBS dentro do painel": "🎛️ パネルの OBS 操作に何を出すか",
    "Marque só o que você usa. Isso muda a ferramenta 🎬 do painel — as teclas 🎬 da Mesa de Trilhas continuam funcionando de qualquer jeito.": "使うものだけチェックしてください。パネルの 🎬 ツールが変わります — サウンドボードの 🎬 キーはどちらでも動きます。",
    "📡 Transmitir, ⏺ gravar, ⏸ pausa, 📷 câmera virtual e ⏪ replay": "📡 配信、⏺ 録画、⏸ 一時停止、📷 仮想カメラ、⏪ リプレイ",
    "🎬 Lista de cenas (clique troca a cena)": "🎬 シーン一覧（クリックでシーンを切り替え）",
    "🎭 Modo estúdio, ✨ mandar o preview ao ar e 🔀 transições": "🎭 スタジオモード、✨ プレビューを本番へ、🔀 トランジション",
    "👁 Mostrar/esconder as fontes da cena que está no ar": "👁 本番中のシーンのソースを表示/非表示",
    "🔊 Mixer: mudo e volume de cada fonte de áudio": "🔊 ミキサー：各音声ソースのミュートと音量",
    "⏯ Controle de mídia (vídeos e playlists do OBS)": "⏯ メディア操作（OBS の動画とプレイリスト）",
    "🎚 Ligar e desligar filtros": "🎚 フィルタのオン/オフ",
    "📸 Print da cena, que cai direto nas mídias do programa": "📸 シーンのキャプチャ。そのままプログラムのメディアに入ります",
    "🗂 Coleções de cenas e 👤 perfis (troca pesada — vem desligado)": "🗂 シーンコレクションと 👤 プロファイル（重い切り替え — 初期はオフ）",
    "— o controle completo do OBS na ferramenta 🎬 do painel: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela. Tudo isso também vira": "— パネルの 🎬 ツールで OBS をまるごと操作：配信、録画（一時停止とチャプターマーカー付き）、仮想カメラ、リプレイ、シーン、スタジオモード、トランジション、ソースの表示/非表示、音声ミキサー、メディア操作、フィルタ、コレクション、プロファイル、画面キャプチャ。これらはすべて",
    "botão na Mesa de Trilhas": "サウンドボードのボタン",
    "🎬 Comandar o OBS (cenas, live/gravação, mixer, fontes, filtros, mídias — e as teclas 🎬 da Mesa)": "🎬 OBS を操作（シーン、配信/録画、ミキサー、ソース、フィルタ、メディア — サウンドボードの 🎬 キーも）",
    "Como controlo o OBS pelo painel?": "パネルから OBS をどう操作しますか？",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). Para linkar: no OBS (28+), abra Ferramentas → Configurações do Servidor WebSocket, marque Ativar servidor WebSocket, clique em Mostrar senha das conexões e copie a porta (4455) e a senha para o card do Labs — o passo a passo numerado está lá. Se o OBS estiver em OUTRO computador da rede, ponha o IP dele no campo Endereço (e libere a porta 4455 no firewall daquela máquina). A ferramenta 🎬 do painel comanda tudo: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay buffer, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela — e cada bloco tem um liga/desliga no card do Labs, para a ferramenta ficar do tamanho que você usa. Tudo dentro do seu computador, sem internet.": "🧪 Labs → 🎬 パネルから OBS Studio（実験的）をオンにします。つなぐには：OBS（28 以降）で ツール → WebSocket サーバー設定 を開き、WebSocket サーバーを有効にする にチェックし、接続情報を表示 をクリックして、ポート（4455）とパスワードを Labs のカードにコピーします — 番号付きの手順もそこにあります。OBS がネットワーク上の別のパソコンにある場合は、そのパソコンの IP をアドレス欄に入れてください（そしてそのマシンのファイアウォールでポート 4455 を通してください）。パネルの 🎬 ツールがすべてを操作します：配信、録画（一時停止とチャプターマーカー付き）、仮想カメラ、リプレイバッファ、シーン、スタジオモード、トランジション、ソースの表示/非表示、音声ミキサー、メディア操作、フィルタ、コレクション、プロファイル、画面キャプチャ — そして各ブロックには Labs カードにオン/オフがあり、ツールを必要な大きさにできます。すべてご自身のパソコンの中で、インターネットは使いません。",
    "Dá para transformar as coisas do OBS em botões?": "OBS の機能をボタンにできますか？",
    "Dá — é a tecla 🎬 Ação do OBS na 🎵 Mesa de trilhas. Crie uma tecla, escolha o tipo 🎬 e depois a ação (trocar de cena, gravar, mudo do microfone, mostrar uma fonte, ligar um filtro, tocar uma mídia...). As listas de cenas, fontes e filtros vêm do OBS conectado; o ▶ Testar agora dispara na hora para você conferir. A tecla acende sozinha quando o que ela controla está ligado (gravando, no ar, fonte visível). Essas teclas também entram dentro de um 🎛️ Botão de multi ação: a fila mistura som e comando — trocar de cena, esperar 2s e tocar a vinheta, por exemplo.": "できます — 🎵 サウンドボードの 🎬 OBS の操作 キーです。キーを作り、種類 🎬 を選び、次に操作を選びます（シーン切り替え、録画、マイクのミュート、ソースの表示、フィルタのオン、メディアの再生など）。シーン・ソース・フィルタの一覧は接続中の OBS から来ます。▶ 今すぐ試す ですぐ実行して確認できます。操作対象がオンのとき（録画中、本番中、ソースが表示中）キーは自分で光ります。これらのキーは 🎛️ マルチアクションボタンの中にも入ります：列は音とコマンドを混ぜられます — 例えばシーンを切り替え、2 秒待ってジングルを鳴らす。",
    // ---------- v0.53: rótulos curtos do editor da tecla 🎬 ----------
