    "🕒 tempo de membro (YouTube)": "🕒 メンバー期間（YouTube）",
    "meses de membro": "か月のメンバー",
    "Meses como membro (0 = membro novo). O YouTube troca o selo em 1, 2, 6, 12, 24, 36... meses.": "メンバーとしての月数（0 = 新規メンバー）。YouTube はバッジを 1、2、6、12、24、36…か月で切り替えます。",
    "🎯 Faixas — por 💰 valor, 🎨 cor do Super Chat, 🔤 palavra no nome ou 🕒 tempo de membro": "🎯 段階 — 💰 金額、🎨 スーパーチャットの色、🔤 名前の言葉、🕒 メンバー期間",
    "Cada faixa escolhe COMO casar: 💰 a partir de um valor em reais (Super Chat, 🎟️ Super Sticker e 💝 doação, qualquer moeda); 🎨 pelo tom que o próprio YouTube pintou no Super Chat ou no Super Sticker; 🔤 por uma palavra que aparece no espaço do nome (o nome, «Membro», o nível do canal...); ou 🕒 a partir de tantos meses como membro do YouTube (o tempo que o selo do membro mostra: novo, 1, 2, 6, 12, 24 meses...). Quando mais de uma serve, a ordem é: cor → valor → palavra → tempo de membro → comentário comum.": "各段階は一致の仕方を選びます：💰 レアル建ての金額以上（スーパーチャット、🎟️ スーパーステッカー、💝 寄付、通貨は問わず）、🎨 YouTube 自身がスーパーチャットやスーパーステッカーに付けた色、🔤 名前の欄に現れる言葉（名前、「メンバー」、チャンネルのレベルなど）、または 🕒 YouTube メンバーとしての月数以上（バッジが示す期間：新規、1、2、6、12、24か月…）。複数当てはまるときの順序：色 → 金額 → 言葉 → メンバー期間 → 通常コメント。",
    "🔑 Palavras para participar (até 30)": "🔑 参加するための言葉（最大30）",
    "Com palavras na lista, só entra no sorteio quem digitar uma delas no chat. Lista vazia: todo mundo que fala entra.": "リストに言葉があると、チャットでそのいずれかを打った人だけが抽選に参加します。リストが空なら、話した人全員が参加します。",
    "Com palavras na lista, só entra quem digitar": "リストに言葉があると、参加できるのは",
    "uma delas": "そのいずれか",
    "no chat — a palavra inteira, sem diferença entre maiúsculas e minúsculas («#sorteio» vale como «sorteio»). Lista vazia = todo mundo que fala entra, como sempre.": "をチャットで打った人だけ — 単語全体、大文字小文字は区別しません（「#抽選」は「抽選」と同じ）。リストが空 = これまで通り話した人全員が参加。",
