    "TUDO do sorteio de volta ao padrão: palavras, fichas, dado, som e resposta (dá para desfazer)": "抽選のすべてを既定に戻す：言葉、チケット、サイコロ、音、返答（取り消し可能）",
    "📏 Pontilhado do modo medida": "📏 計測モードの点線",
    "Quanto o contorno pontilhado branco aparece enquanto você digita no seletor manual (modo medida). Preferência deste navegador.": "手動サイズ欄に入力しているとき（計測モード）の白い点線の見えやすさ。このブラウザーの設定です。",
    "Mais visível": "より見やすく",
    "Bem visível": "とても見やすく",
    "📺 Por rede — cada uma pode vestir o seu próprio molde de comentário comum": "📺 ネットワーク別 — それぞれが通常コメント用の独自テンプレートを着られます",
    "Um molde marcado como exclusivo de uma rede (▶️ 💜 🟢 💙) nunca veste comentário de outra. Aqui você diz o que cada rede veste quando nenhuma faixa casa: o comum acima, um molde só dela ou o visual ao vivo (sem molde).": "ある配信サービス専用（▶️ 💜 🟢 💙）とマークしたテンプレートは、他のサービスのコメントを着ることはありません。ここでは、どの段階にも当てはまらないときに各サービスが何を着るかを指定します：上の通常テンプレート、そのサービス専用のテンプレート、またはライブの見た目（テンプレートなし）。",
    "💰 Super Chat ou doação que não casa com faixa nenhuma veste": "💰 どの段階にも当てはまらないスーパーチャットや寄付が着るもの",
    "— o mesmo do comentário comum —": "— 通常コメントと同じ —",
    "— o visual ao vivo (sem molde) —": "— ライブの見た目（テンプレートなし）—",
    "— o mesmo do comentário comum da rede —": "— そのサービスの通常コメントと同じ —",
    "⚠️ O visual ao vivo (quem veste tudo que não casa com molde) está com a arte «{arte}». Se a ideia era a arte só nos moldes, tire-a do visual ao vivo:": "⚠️ ライブの見た目（テンプレートに当てはまらないものすべてが着るもの）にアート「{arte}」が付いています。アートをテンプレートだけに使うつもりなら、ライブの見た目から外してください：",
    "🎭 Editando:": "🎭 編集中：",
    "Qual visual do destaque esta aba ajusta: o visual ao vivo (sem molde) ou um molde salvo. É o mesmo seletor 🎭 Editando do 🖱️ Organizar a tela.": "このタブが調整するハイライトの見た目：ライブの見た目（テンプレートなし）か保存済みテンプレート。🖱️ 画面を整理する の 🎭 編集中 セレクターと同じです。",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — o que você ajusta aqui vai para o visual ao vivo, que a tela NÃO está mostrando agora. Abra o molde para mudar o que está na tela.": "⚠️ 放送中のコメントは 🎭 自動によりテンプレート「{molde}」を着ています — ここでの調整はライブの見た目に入りますが、画面は今それを表示していません。画面上のものを変えるにはテンプレートを開いてください。",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — você está ajustando «{editando}». Abra «{molde}» para mudar o que está na tela.": "⚠️ 放送中のコメントは 🎭 自動によりテンプレート「{molde}」を着ています — 今調整しているのは「{editando}」です。画面上のものを変えるには「{molde}」を開いてください。",
    "🎭 Abrir «{molde}»": "🎭 「{molde}」を開く",
    "✍️ Formatação dos textos": "✍️ 文字の書式",
    "Qual texto": "どのテキスト",
    "Cada texto tem a sua formatação": "各テキストに独自の書式があります",
    "Fonte da letra deste texto (Padrão = a fonte do overlay)": "このテキストのフォント（既定 = オーバーレイのフォント）",
    "Como está = do jeito que é de fábrica": "そのまま = 初期の見た目",
    "Cor própria deste texto (por cima das cores gerais do overlay)": "このテキスト独自の色（オーバーレイ全体の色より優先）",
    "Formatação deste texto de volta ao padrão": "このテキストの書式を既定に戻す",
    "📢 Texto do aviso": "📢 お知らせの本文",
    "Vale em qualquer modo (cartão padrão, molde com arte ou overlay em peças) — é a mesma formatação da linha ✍️ do 🖱️ Organizar a tela.": "どのモードでも有効です（標準カード、アート付きテンプレート、パーツ化オーバーレイ）— 🖱️ 画面を整理する の ✍️ 行と同じ書式です。",
    "Vale com o widget nos presets de sempre ou solto em peças — é a mesma formatação da linha ✍️ do 🖱️ Organizar a tela.": "ウィジェットが通常のプリセットでもパーツ分解でも有効です — 🖱️ 画面を整理する の ✍️ 行と同じ書式です。",
    "Cada texto do chat tem a sua formatação: o nome de quem comenta e o texto do comentário.": "チャットの各テキストに独自の書式があります：コメントした人の名前とコメント本文。",
