    "Cor do contorno": "縁取りの色",
    "✍️ Formatação da letra: clique numa peça com texto (nome, texto, valor, títulos, números...) e os ajustes de fonte, negrito, contorno... aparecem aqui.": "✍️ 文字の書式：テキストを持つパーツ（名前、本文、金額、タイトル、数字...）をクリックすると、フォント・太字・縁取りなどの設定がここに表示されます。",
    "✍️ «{peca}» é imagem ou caixa, não tem letra para formatar — clique numa peça com texto (nome, texto, valor, títulos, números...).": "✍️ 「{peca}」は画像またはボックスで、書式を設定する文字がありません — テキストを持つパーツ（名前、本文、金額、タイトル、数字...）をクリックしてください。",
    "A formatação vale só para esta peça — cada peça com texto tem a sua": "書式はこのパーツにのみ適用されます — テキストを持つ各パーツが独自の書式を持ちます",
