    "Centralizar na tela (leva esta peça para o meio do canvas)": "画面中央に配置（このパーツをキャンバスの中央へ移動）",
    "Na live, este comentário vestiria o molde": "配信ではこのコメントは次のテンプレートを使います",
    "A prévia mostra o visual ao vivo, que é o que você está editando — para ajustar o molde, abra-o no seletor 🎭 Editando.": "プレビューは編集中のライブの見た目を表示しています — テンプレートを調整するには、🎭 編集セレクターで開いてください。",
    "Clique num overlay ou numa peça para ver e digitar as medidas dele.": "オーバーレイまたはパーツをクリックすると、寸法の確認と入力ができます。",
    "🧩 Clique numa peça do mapa para ajustá-la aqui (tamanho, caixa, giro, opacidade, cor...).": "🧩 マップ上のパーツをクリックすると、ここで調整できます（サイズ、ボックス、回転、不透明度、色...）。",
    "👤 Avatar": "👤 アバター",
