    "🎨 Editor visual de overlay": "🎨 ビジュアルオーバーレイエディター",
    "A sua tela (16:9) inteira como mesa de trabalho — mecânica do editor do": "あなたの画面（16:9）全体が作業台に — 次のエディターの仕組み:",
    "Arraste cada elemento": "各要素をドラッグ",
    "(salva sozinho, muda na live na hora), puxe as": "（自動保存、配信は即反映)、",
    "para o tamanho, e use a barra": "で大きさを変え、マップのすぐ下のバー",
