    "Números em": "数値は",
    "pixels": "ピクセル",
    "Clique num elemento para selecioná-lo no mapa. As setinhas ▲▼ mudam a": "要素をクリックするとマップで選択されます。▲▼ の矢印はその",
    "camada": "レイヤー",
    "dele (quem fica por cima — vale na live de verdade). O 👁 esconde só aqui no editor; o 🔒 trava contra esbarrões.": "を変えます（どれが上に乗るか — 本番の配信で有効)。👁 はこのエディター内だけで隠し、🔒 はうっかり触りを防ぎます。",
    "🎭 Troca automática — cada comentário destacado veste o perfil certo sozinho": "🎭 自動切り替え — 注目コメントごとに正しいプロフィールをひとりでに着ます",
    "Ligar a troca automática": "自動切り替えをオンにする",
    "— um seletor para cada overlay/widget. Para moldura de tela inteira, crie em 1920×1080 com fundo transparente (PNG ou WebM). O fundo do comentário em destaque se escolhe lá em cima, na linha": "— オーバーレイ/ウィジェットごとにセレクターが 1 つ。全画面フレームは 1920×1080・透過背景（PNG か WebM)で作成を。注目コメントの背景は上の行",
    "— e com um molde em edição, a arte escolhida grava DENTRO do perfil.": "で選びます — 型を編集中なら、選んだアートはプロフィールの中に保存されます。",
    "Veste o perfil escolhido AGORA no visual ao vivo do destaque (dá para desfazer no ◀)": "選んだプロフィールを今すぐ注目のライブの見た目に着せます（◀ で取り消せます）",
    "nome do perfil novo": "新しいプロフィールの名前",
    "Uma camada para cima (fica por cima na live)": "1 レイヤー上へ（配信で上に乗ります）",
    "Uma camada para baixo": "1 レイヤー下へ",
    "Uma camada para cima dentro deste item": "この要素の中で 1 レイヤー上へ",
    "Uma camada para baixo dentro deste item": "この要素の中で 1 レイヤー下へ",
