    "🕐 sai quando o relógio chegar na data/hora preenchida · ⏳ sai quando faltar esse tempo no timer. Disparou uma vez, os números voltam a 00.": "🕐 時計が入力した日時に達すると消えます · ⏳ タイマーの残りがこの時間になると消えます。一度発動すると数字は 00 に戻ります。",
    "Se o ⏳ Timer estiver combinado com os Avisos, o recado também sai sozinho quando o tempo acabar.": "⏳ タイマーがお知らせと連携していれば、時間切れのときにもメッセージは自動で消えます。",
