    "🎬 OBS Studio Remoto": "🎬 OBS Studio リモート",
    "🎵 Mesa de Trilhas": "🎵 トラックデッキ",
    "A conexão e o controle completo do OBS Studio pelo painel. Esta página fica disponível enquanto o seletor 🎬 estiver ligado na aba 🧪 Labs.": "パネルからの OBS Studio の接続と完全なコントロール。このページは 🧪 Labs タブの 🎬 スイッチがオンの間だけ利用できます。",
    "As trilhas, a grade de botões e a importação do Stream Deck. Esta página fica disponível enquanto o seletor 🎵 estiver ligado na aba 🧪 Labs.": "トラック、ボタングリッド、Stream Deck のインポート。このページは 🧪 Labs タブの 🎵 スイッチがオンの間だけ利用できます。",
    "⚙️ Ligado, a configuração completa mora na página «🎬 OBS Studio Remoto» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ オンにすると、完全な設定は左メニューの「🎬 OBS Studio リモート」ページにあります(🎨 テーマのすぐ後)。",
    "⚙️ Ligada, a configuração completa mora na página «🎵 Mesa de Trilhas» do menu à esquerda (logo depois de 🎨 Temas).": "⚙️ オンにすると、完全な設定は左メニューの「🎵 トラックデッキ」ページにあります(🎨 テーマのすぐ後)。",
    "A porta e a senha ficam na página «🎬 OBS Studio Remoto» das configurações.": "ポートとパスワードは設定の「🎬 OBS Studio リモート」ページにあります。",
    "⌨️ Atalhos do OBS": "⌨️ OBS のホットキー",
    "Qualquer coisa com atalho no OBS (até de plugin) dispara daqui — é o coringa do que ainda não tem botão próprio.": "OBS でホットキーがあるものなら(プラグインのものでも)ここから発動できます — まだ専用ボタンがないもののためのワイルドカードです。",
    "Disparar este atalho no OBS": "このホットキーを OBS で発動",
    "Há quanto tempo a transmissão está no ar": "配信が始まってからの経過時間",
