    "Quadros por segundo que o OBS está desenhando": "OBS が描画している毎秒フレーム数",
    "Uso de processador pelo OBS": "OBS のプロセッサー使用率",
    "Memória usada pelo OBS": "OBS が使用中のメモリ",
    "Espaço livre no disco das gravações": "録画用ディスクの空き容量",
    "Quadros perdidos (desenho + saída + rede) — sinal de aperto na máquina ou na internet": "損失フレーム(描画+出力+ネットワーク)— マシンか回線が苦しいサインです",
    "📊 Saúde do OBS: fps, CPU, memória, disco, quadros perdidos e tempos de transmissão/gravação": "📊 OBS の健康状態:fps、CPU、メモリ、ディスク、損失フレーム、配信/録画時間",
    "⌨️ Disparar atalhos do OBS por nome — o coringa do que não tem botão próprio (vem desligado)": "⌨️ OBS のホットキーを名前で発動 — 専用ボタンがないもののワイルドカード(既定オフ)",
    "🎬 Criar teclas do OBS na Mesa (escolha o que quiser)": "🎬 デッキに OBS キーを作成(好きなものを選択)",
    "Marque os recursos do seu OBS e aperte ➕: cada um vira uma tecla DE VERDADE na Mesa — dá para mover, renomear, colorir e apagar como qualquer outra. Depois de criar, é só arrastar cada tecla para a célula que quiser.": "OBS のリソースにチェックを入れて ➕ を押すと、それぞれがサウンドボードの本物のキーになります —— 他のキーと同じように移動・改名・色付け・削除できます。作ったら、各キーを好きなマスにドラッグするだけです。",
    "➕ Criar as teclas marcadas": "➕ チェックしたキーを作成",
    "Conecte o 🎬 OBS Studio (página OBS Studio Remoto) para listar os recursos dele aqui.": "🎬 OBS Studio を接続すると(OBS Studio リモートページ)、そのリソースがここに並びます。",
