    "Altura máxima da mídia no modo janela, em % da tela do público": "ウィンドウモードでのメディアの最大高さ(視聴者画面の%)",
    "O clique na tecla mostra a mídia no painel E no overlay (no overlay só a imagem/vídeo aparecem); clicar de novo tira. Na janela, o overlay contorna a mídia com a sombra dos overlays (a mesma do 🔍 mostrar avatar — ajuste em 🎨 Aparência). O vídeo sai sozinho quando termina.": "キーをクリックするとメディアがパネルとオーバーレイの両方に表示されます(オーバーレイには画像/動画だけ)。もう一度クリックで消えます。ウィンドウモードではオーバーレイの影(🔍 アバター表示と同じ — 🎨 外観で調整)がメディアを縁取ります。動画は終わると自動で消えます。",
    "🎵 toca um som · 🖼️/🎞️ mostra uma imagem ou vídeo no painel e no overlay (janela redimensionável ou tela cheia) · 🎬 Ação do OBS: comanda o OBS Studio (gravar, trocar de cena, mudo...) · 🎛️ Botão de multi ação: guarda teclas e o clique toca tudo em fila (segurar abre) · 📁 Pasta simples: só guarda teclas — o clique abre, nada toca": "🎵 音を鳴らす · 🖼️/🎞️ パネルとオーバーレイに画像や動画を表示(ウィンドウまたは全画面) · 🎬 OBS アクション:OBS Studio を操作(録画、シーン切替、ミュート…) · 🎛️ マルチアクションボタン:キーを収め、クリックで順番に再生(長押しで開く) · 📁 シンプルフォルダー:キーを収めるだけ — クリックで開き、何も再生しない",
    "✨ Sombra dos overlays": "✨ オーバーレイの影",
    "Suave — a do 🔍 mostrar avatar (padrão)": "ソフト — 🔍 アバター表示の影(既定)",
    "Contorno marcado": "はっきりした輪郭",
