    "Opacidade": "不透明度",
    "Contorna o 🔍 avatar, a 📎 mídia do inscrito, as 🖼️🎞️ mídias da Mesa de Trilhas e o 💬 cartão de destaque (com «Sombra no cartão» ligada) — o mesmo padrão em todos.": "🔍 アバター、📎 視聴者のメディア、🖼️🎞️ トラックデッキのメディア、💬 注目カード(「カードに影」オン時)を縁取ります — すべて同じ基準です。",
    "Tirar a mídia da tela (painel e overlay)": "メディアを画面から外す(パネルとオーバーレイ)",
