    "Marcado, a velocidade muda o tom (voz de desenho/lentidão); desmarcado, a voz fica natural": "オンにすると速度で声の高さが変わります(アニメ声/スロー声)。オフなら声は自然なまま",
    "Velocidade da mídia na tela do público (0.05× a 32×, de 0.01 em 0.01)": "視聴者画面のメディアの速度(0.05×〜32×、0.01 刻み)",
    "🥇 Nítida (padrão)": "🥇 シャープ(既定)",
