    // 🎞️ v0.129: mídia direta (URL ou arquivo do computador, direto para a tela)
    "Mídia direta: imagem, vídeo ou áudio de uma URL ou do computador": "ダイレクトメディア：URL またはパソコンから画像・動画・音声",
    "🎞️ Mídia direta": "🎞️ ダイレクトメディア",
    "Cole a URL (YouTube, TikTok, Instagram, Discord, arquivo…)": "URL を貼り付け（YouTube、TikTok、Instagram、Discord、ファイル…）",
    "Carregar a mídia (a tela fica como está: use o 👁️ para mostrar)": "メディアを読み込む（画面はそのまま：表示するには 👁️ を使用）",
    "Carregar": "読み込む",
    "Carregar e já mostrar na tela do público": "読み込んですぐに視聴者の画面に表示",
    "📂 Do computador (o arquivo fica onde está — nada sobe para a biblioteca)": "📂 パソコンから（ファイルはその場のまま — ライブラリには何も上がりません）",
